// One-off migration runner: applies the SQL files in src/db/migrations in order.
// Run from payroll-automation/backend so pg/dotenv resolve from its node_modules.
const path = require('path');
const fs = require('fs');
require('dotenv').config({ path: path.resolve(process.cwd(), '../.env') });
const { Pool } = require('pg');

const dir = path.resolve(process.cwd(), 'src/db/migrations');
const files = fs.readdirSync(dir).filter((f) => f.endsWith('.sql')).sort();

(async () => {
  const pool = new Pool({ connectionString: process.env.DATABASE_URL });
  for (const f of files) {
    const sql = fs.readFileSync(path.join(dir, f), 'utf8');
    console.log('applying', f);
    await pool.query(sql);
  }
  const res = await pool.query(
    "SELECT table_name FROM information_schema.tables WHERE table_schema='public' ORDER BY 1"
  );
  console.log('tables now in database:', res.rows.map((r) => r.table_name).join(', '));
  await pool.end();
})().catch((err) => {
  console.error('migration failed:', err.message);
  process.exit(1);
});

